public static double value(int n, int k) {
        BinomialCoefficient.checkBinomial(n, k);

        if (n == k ||
            k == 0) {
            return 1;
        }
        if (k == 1 ||
            k == n - 1) {
            return n;
        }
        if (k > n / 2) {
            return value(n, n - k);
        }
        if (n < 67) {
            return BinomialCoefficient.value(n, k);
        }

        double result = 1;
        for (int i = 1; i <= k; i++) {
            result *= n - k + i;
            result /= i;
        }

        return Math.floor(result + 0.5);
    }

